const normalizePolicyComponentValue = (value: unknown) =>
  String(value ?? "")
    .trim()
    .toLowerCase();

const policyComponentToTextOrNull = (value: unknown): string | null => {
  const text = String(value ?? "").trim();
  return text ? text : null;
};

const isPolicyComponentYes = (value: unknown) =>
  normalizePolicyComponentValue(value) === "yes";

const isPolicyComponentTrue = (value: unknown) => {
  const normalized = normalizePolicyComponentValue(value);
  return normalized === "true" || normalized === "yes" || value === true;
};

const pickPolicyComponentEligibleRelations = (row: PolicyComponentExcelRow) =>
  Object.keys(row)
    .filter((key) => !POLICY_COMPONENT_KNOWN_KEYS.has(key))
    .filter((key) => isPolicyComponentYes(row[key]))
    .map((key) => POLICY_COMPONENT_RELATION_KEY_TO_LABEL[key] ?? key);

const policyComponentKeyify = (value: unknown) =>
  String(value ?? "")
    .toLowerCase()
    .trim()
    .replace(/[\u2013\u2014]/g, "-")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const policyComponentSetDeep = (
  obj: Record<string, unknown>,
  path: string[],
  value: unknown,
) => {
  let current: Record<string, unknown> = obj;
  for (let i = 0; i < path.length - 1; i += 1) {
    const key = path[i];
    if (current[key] == null || typeof current[key] !== "object") {
      current[key] = {};
    }
    current = current[key] as Record<string, unknown>;
  }
  current[path[path.length - 1]] = value;
};

const ensurePolicyComponentTemplateSection = (
  cfg: Record<string, unknown>,
  sectionKey: "basePolicy" | "parentalPolicy",
) => {
  if (!cfg.policyTemplate || typeof cfg.policyTemplate !== "object") {
    cfg.policyTemplate = {};
  }
  const policyTemplate = cfg.policyTemplate as Record<string, unknown>;
  if (!policyTemplate[sectionKey]) policyTemplate[sectionKey] = {};
  const section = policyTemplate[sectionKey] as Record<string, unknown>;
  if (!Array.isArray(section.addonIds)) section.addonIds = [];
};

const findPolicyComponentId = (
  cfg: Record<string, unknown>,
  compType: string,
  compLabel: string,
): number | null => {
  const components = Array.isArray((cfg as any)?.components)
    ? ((cfg as any).components as Array<Record<string, unknown>>)
    : [];

  const normalizedType = normalizePolicyComponentValue(compType);
  const normalizedLabel = policyComponentKeyify(compLabel);

  const byTypeLabel = components.find(
    (component) =>
      normalizePolicyComponentValue(component?.type) === normalizedType &&
      policyComponentKeyify(component?.label) === normalizedLabel,
  );
  if (byTypeLabel?.id) return Number(byTypeLabel.id);

  const byLabel = components.find(
    (component) => policyComponentKeyify(component?.label) === normalizedLabel,
  );
  if (byLabel?.id) return Number(byLabel.id);

  const byType = components.find(
    (component) =>
      normalizePolicyComponentValue(component?.type) === normalizedType,
  );
  if (byType?.id) return Number(byType.id);

  const partial = components.find(
    (component) =>
      normalizePolicyComponentValue(component?.type) === normalizedType &&
      policyComponentKeyify(component?.label).includes(normalizedLabel),
  );
  if (partial?.id) return Number(partial.id);

  return null;
};

const getCellValue = (row: any, ...aliases: string[]) => {
  const normalizedAliases = aliases.map((a) =>
    a.replace(/[\s_]+/g, "").toLowerCase(),
  );
  for (const key of Object.keys(row)) {
    const normalizedKey = key.replace(/[\s_]+/g, "").toLowerCase();
    if (normalizedAliases.includes(normalizedKey)) {
      return row[key];
    }
  }
  return undefined;
};

