// Option A: digits first → letters → special chars → nulls (handled by caller)
function alphanumericPolicySort(a: string, b: string): number {
  const group = (v: string) => (/^\d/.test(v) ? 0 : /^[a-zA-Z]/.test(v) ? 1 : 2);
  const gDiff = group(a) - group(b);
  if (gDiff !== 0) return gDiff;
  const parts = (s: string) => s.match(/\d+|\D+/g) || [];
  const [ap, bp] = [parts(a), parts(b)];
  for (let i = 0; i < Math.max(ap.length, bp.length); i++) {
    if (i >= ap.length) return -1;
    if (i >= bp.length) return 1;
    if (/^\d+$/.test(ap[i]) && /^\d+$/.test(bp[i])) {
      const d = parseInt(ap[i], 10) - parseInt(bp[i], 10);
      if (d !== 0) return d;
    } else {
      const [au, bu] = [ap[i].toUpperCase(), bp[i].toUpperCase()];
      if (au < bu) return -1;
      if (au > bu) return 1;
    }
  }
  return 0;
}

const composeFullName = (
  firstName?: string,
  middleName?: string,
  lastName?: string,
): string => {
  const isNonEmptyString = (value?: string | null): boolean =>
    !!value && value.trim().length > 0;

  if (!isNonEmptyString(firstName)) return DEFAULT_CONTACT_NAME;
  return [firstName, middleName, lastName].filter(isNonEmptyString).join(" ");
};

const formatDate = (date: string | Date): string | null => {
  if (!date) return null;
  const parsedDate = new Date(date);
  if (Number.isNaN(parsedDate.getTime())) {
    return null;
  }
  return parsedDate.toISOString().split("T")[0]; // Extract only the date part (YYYY-MM-DD)
};

const formatDateTime = (date: string | Date): string | null => {
  if (!date) return null;
  const parsedDate = new Date(date);
  if (Number.isNaN(parsedDate.getTime())) {
    return null;
  }
  return parsedDate.toISOString();
};

// Formats a date as "Mon-YYYY" (e.g. "Jun-2026"), matching the Biz Done report's
// TO_CHAR(..., 'Mon-YYYY') display for business_month / income_month.
const MONTHS_SHORT = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const formatMonthYear = (date: string | Date): string | null => {
  if (!date) return null;
  // A `date` column comes back as a "YYYY-MM-DD" string — parse the parts directly
  // so the month is never shifted by the server timezone (matches SQL TO_CHAR).
  if (typeof date === "string") {
    const m = date.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) {
      return `${MONTHS_SHORT[Number(m[2]) - 1]}-${Number(m[1])}`;
    }
  }
  const parsedDate = new Date(date);
  if (Number.isNaN(parsedDate.getTime())) {
    return null;
  }
  return `${MONTHS_SHORT[parsedDate.getUTCMonth()]}-${parsedDate.getUTCFullYear()}`;
};

const getFinancialYear = (date?: Date): string | null => {
  if (!date) return null;
  const d = new Date(date);
  const year = d.getFullYear();
  const month = d.getMonth();
  const startYear = month >= 3 ? year : year - 1;
  return `${startYear}-${startYear + 1}`;
};

