const createLookup = (
  lookup?: LookUp | null,
  fallbackId?: number | null,
  fallbackValue?: string | null,
) => ({
  id: lookup?.id ?? fallbackId ?? null,
  lookUpValue: lookup?.lookUpValue ?? fallbackValue ?? null,
  lookUpKey: lookup?.lookUpKey ?? null,
});

const resolveLookupByIdOrKey = async (
  repo: Repository<LookUp>,
  lookupId: number | null | undefined,
  fallbackKey?: string,
) => {
  if (lookupId != null) {
    const lookup = await repo.findOne({
      where: { id: lookupId },
      select: ["id", "lookUpValue", "lookUpKey"],
    });
    if (lookup) return lookup;
  }

  if (!fallbackKey) return null;

  return repo.findOne({
    where: { lookUpKey: fallbackKey },
    select: ["id", "lookUpValue", "lookUpKey"],
  });
};

const createNamedEntity = (
  id?: number | null,
  displayName?: string | null,
) => ({
  id: id ?? null,
  displayName: displayName ?? null,
});

const createUserContactDetails = (details: ResolvedUserDetails) => ({
  id: details.id,
  firstName: details.firstName,
  lastName: details.lastName,
  name: details.name,
  empId: details.empId,
  email: details.email,
  mobile: details.phone,
  branch: details.branch,
});

const createAddressDetails = (address?: Address | null) => {
  if (!address) {
    return {
      id: null,
      addressTypeLid: null,
      addressType: createLookup(),
      branchType: createLookup(),
      branchCode: null,
      address1: null,
      address2: null,
      area: null,
      country: createNamedEntity(),
      state: createNamedEntity(),
      city: createNamedEntity(),
      pincode: null,
      phoneNumber: null,
      alternatePhoneNumber: null,
      email: null,
      supportNumber: null,
      fax: null,
    };
  }

  const countryRelation: any = address.countryId;
  const stateRelation: any = address.stateId;
  const cityRelation: any = address.cityId;
  const addressTypeRelation: any = (address as any).addressType;

  return {
    id: address.id ?? null,
    addressTypeLid: address.addressTypeLid ?? null,
    addressType: createLookup(
      addressTypeRelation ?? null,
      address.addressTypeLid ?? null,
    ),
    branchType: createLookup(
      (address as any).branchType ?? null,
      (address as any).branchTypeLid ?? null,
    ),
    branchCode: (address as any).branchCode ?? null,
    address1: address.address1 ?? null,
    address2: address.address2 ?? null,
    area: address.area ?? null,
    country: createNamedEntity(
      countryRelation?.id ?? null,
      countryRelation?.name ?? null,
    ),
    state: createNamedEntity(
      stateRelation?.id ?? null,
      stateRelation?.name ?? null,
    ),
    city: createNamedEntity(
      cityRelation?.id ?? null,
      cityRelation?.name ?? null,
    ),
    pincode: address.pinCode ?? null,
    phoneNumber: address.phoneNumber ?? null,
    alternatePhoneNumber: address.alternatePhoneNumber ?? null,
    email: address.email ?? null,
    supportNumber: address.supportNumber ?? null,
    fax: (address as any)?.fax ?? null,
  };
};

const createContactDetails = (
  contact: Contact | null | undefined,
  emailDetail: CommunicationDetail,
  phoneDetail: CommunicationDetail,
) => {
  if (!contact) {
    return {
      id: null,
      firstName: null,
      lastName: null,
      middleName: null,
      displayName: null,
      companyLocation: createNamedEntity(),
      companyBranch: null,
      contactTypeLid: null,
      contactType: createLookup(),
      department: null,
      designation: null,
      reportingTo: null,
      assistant: null,
      remarks: null,
      statusLid: null,
      status: createLookup(),
      email: null,
      emailCommunicationId: null,
      phoneNumber: null,
      phoneCommunicationId: null,
    };
  }

  const companyLocation: any = (contact as any).companyLocation;
  const statusRelation: any = (contact as any).status;
  const contactTypeRelation: any = (contact as any).contactType;

  return {
    id: contact.id ?? null,
    firstName: contact.firstName ?? null,
    lastName: contact.lastName ?? null,
    middleName: contact.middleName ?? null,
    displayName: contact.displayName ?? null,
    companyLocation: createNamedEntity(
      companyLocation?.id ?? null,
      companyLocation?.name ?? null,
    ),
    companyBranch: contact.companyBranchId ?? null,
    contactTypeLid: contact.contactTypeLid ?? null,
    contactType: createLookup(
      contactTypeRelation ?? null,
      contact.contactTypeLid ?? null,
    ),
    department: contact.department ?? null,
    designation: contact.designation ?? null,
    reportingTo: contact.reportingToId ?? null,
    assistant: null,
    remarks: contact.remarks ?? null,
    statusLid: contact.statusLid ?? null,
    status: createLookup(statusRelation ?? null, contact.statusLid ?? null),
    email: emailDetail.value,
    emailCommunicationId: emailDetail.id,
    phoneNumber: phoneDetail.value,
    phoneCommunicationId: phoneDetail.id,
  };
};

const createCommunication = (
  detail: CommunicationDetail,
): CommunicationDetail => ({
  id: detail.id ?? null,
  value: detail.value ?? null,
});

const getCommunicationDetail = (
  contact: Contact | null | undefined,
  type: string,
): CommunicationDetail => {
  if (!contact || !Array.isArray(contact.communicationDetails)) {
    return { value: null, id: null };
  }
  const match = contact.communicationDetails.find(
    (detail: ContactCommunicationDetails) =>
      detail.communicationType?.toLowerCase() === type,
  );
  return {
    value: match?.communicationDetails ?? null,
    id: match?.id ?? null,
  };
};

const resolveUserDetails = (
  userMap: Map<number, User>,
  id?: number | null,
): ResolvedUserDetails => {
  const user = typeof id === "number" ? userMap.get(id) : undefined;
  if (!user) {
    return {
      id: null,
      firstName: null,
      lastName: null,
      name: null,
      empId: null,
      email: null,
      phone: null,
      branch: null,
    };
  }
  return {
    id: user.userId ?? null,
    firstName: user.firstName ?? null,
    lastName: user.lastName ?? null,
    name: composeFullName(user.firstName, undefined, user.lastName),
    empId: user.userId ?? null,
    email: user.emailId ?? null,
    phone: user.mobile ?? null,
    branch: user.branch?.name ?? null,
  };
};

