  transformPolicyResponse = (policy: any): any => {
    if (!policy) {
      return null;
    }
    return {
      headerDetails: {
        policyPeriod: `${policy.policyFrom} - ${policy.policyTo}`,
        updatedSumInsured: policy.sumInsured || 0,
        updatedPremium: policy.premiumAtInception || 0,
        serviceLevel: policy?.opportunity?.serviceLevel?.lookUpValue ?? null,
        displayName: policy?.policyName ?? null,
        status: policy?.policyStatus?.lookUpValue ?? null,
      },
      additionalDetails: {
        createdBy: policy?.createdBy ?? null,
        lastModifiedBy: policy?.updatedBy ?? null,
        createdOn: formatDate(policy?.createdAt) ?? null, // Format createdAt to date only
        lastModifiedOn: formatDate(policy.updatedAt) ?? null, // Format updatedAt to date only
      },
      basicDetails: {
        premiumAtInception: policy.premiumAtInception || 0,
        sumInsuredAtInception: policy.sumInsured || 0,
        gstPercentage: policy.gstPercentage || 0,
        gst: policy.gst || 0,
        insurerPolicyNumber: policy?.insurerPolicyNumber ?? null,
        provisionalPolicyNumber: policy?.provisionalPolicyNo ?? null,
        policyBDOwner: policy.opportunity?.bdExecutive ?? null,
        policyISGwner: policy.opportunity?.assignedTo ?? null,
        premiumCalculationType: policy?.premiumCalculationType ?? null,
        premiumCalculationValues: policy?.premiumCalculationValues || 0,
        commissionOnTerrorism: policy?.commissionTerrorism ?? null,
        others: null,
        financialYear: getFinancialYear(policy?.incomeMonth),
        policyIssueDate: formatDate(policy?.dateOfIncome) ?? null,
        incomeMonth: formatDate(policy?.incomeMonth) ?? null,
        policyStartDate: formatDate(policy?.policyFrom) ?? null,
        policyEndDate: formatDate(policy?.policyTo) ?? null,
      },
      cdDetails:
        policy.cdMappings?.map((cdMappings) => ({
          date: formatDate(cdMappings.cdDetail?.chequeDate),
          cdNumber: cdMappings?.cdDetail?.chequeNumber ?? null,
          transactionDetails:
            cdMappings?.cdDetail?.transactionType.lookUpValue ?? null,
          debit: cdMappings?.cdDetail?.chequeAmount || 0,
          credit: cdMappings?.cdDetail?.selectCdAccount ?? null,
          balance: cdMappings?.cdDetail?.openBalance || 0,
        })) || [],
    };
  };

  transformPoliciesResponse(policies: any[]): any[] {
    if (!policies || policies.length === 0) {
      return [];
    }

    return policies.map((policy) => ({
      id: policy.id,
      policyName: policy?.insurerPolicyNumber ?? policy?.policyName ?? null,
      companyName:
        policy?.company?.companyName ?? policy?.company?.displayName ?? null,
      contact:
        policy?.opportunity?.opportunityContactMap?.[0]?.contact?.displayName ??
        null,
      opportunityId: policy?.opportunityId ?? null,
      policyType: policy?.policyType?.lookUpValue ?? null,
      status: policy?.policyStatus?.lookUpValue ?? null,
      sumInsured: policy?.sumInsured ?? null,
      premium: policy?.premiumAtInception ?? null,
      brokerage: policy?.basicBrokerageAmount ?? null,
      insurerCompany:
        policy?.insurerMappings
          ?.map((m: any) => m?.insurer?.displayName ?? m?.insurer?.insurerName)
          .filter(Boolean)
          .join(", ") || null,
      tpa:
        policy?.tpaMappings
          ?.map((m: any) => m?.tpa?.displayName ?? m?.tpa?.tpaName)
          .filter(Boolean)
          .join(", ") || null,
      policyFrom: policy?.policyFrom ?? null,
      policyTo: policy?.policyTo ?? null,
      accountManager: policy?.owner
        ? `${policy.owner.firstName ?? ""} ${
            policy.owner.lastName ?? ""
          }`.trim()
        : null,
      policyNumber: policy?.insurerPolicyNumber ?? null,
    }));
  }

