  async getPolicyConfigurationApproverDetails(policyId: number) {
    try {
      const taskTypeApproval = await this.lookUpRepository.findOne({
        where: { lookUpKey: TASK_TYPE.APPROVAL },
      });

      if (!taskTypeApproval) {
        return null;
      }

      // Simplified query to match the working SQL - only filter by policyId and taskOrigin
      const tasks = await this.taskRepository.find({
        where: {
          policyId,
          taskTypeLid: taskTypeApproval.id,
          taskOrigin: TASK_ORIGIN.POLICY_CONFIGURATION_APPROVAL,
        },
        order: { updatedAt: "DESC" },
        relations: ["assignee"],
      });

      const task = tasks && tasks[0] ? tasks[0] : null;
      if (!task) {
        return null;
      }

      // Get the approver ID: updatedBy if task is closed, otherwise assignee
      const approverId = task.taskClose ? task.updatedBy : task.assignee?.userId;
      
      if (!approverId) {
        return null;
      }

      const approver = await this.userRepository.findOne({
        where: { userId: approverId },
      });

      if (!approver) {
        return null;
      }

      // Extract date and time from the task's updatedAt when it was closed
      let approvedOn: string | null = null;
      let approvedTime: string | null = null;
      if (task.taskClose && task.updatedAt) {
        const istDate = convertUtcToIst(task.updatedAt);
        const { date, time } = extractDateAndTime(istDate);
        approvedOn = date;
        approvedTime = time;
      }

      return {
        id: approver.userId,
        name: approver.firstName,
        status: {
          approvedOn: approvedOn,
          approvedTime: approvedTime,
        },
      };
    } catch (error) {
      this.logger.error({
        level: "error",
        message: buildLogMessage({
          traceId: this.traceIdService.traceId,
          status: "failure",
          location: "PolicyRepository",
          method: "getPolicyConfigurationApproverDetails",
          payload: { policyId },
          messageData: error instanceof Error ? error.message : error,
        }),
      });
      return null;
    }
  }

