  async getPolicyConstraintsByPolicyId(policyId: number) {
    try {
      this.logger.log({
        level: "info",
        message: buildLogMessage({
          traceId: this.traceIdService.traceId,
          status: "success",
          location: "PolicyRepository",
          method: "getPolicyConstraintsByPolicyId",
          payload: { policyId },
          messageData: "method invoked",
        }),
      });
      const policy = await this.policyRepository.manager.findOne(Policy, {
        where: { id: policyId },
        relations: ["company", "company.country"],
      });

      if (!policy) {
        throw new NotFoundException(`Policy with ID ${policyId} not found.`);
      }

      const countryId = policy.company?.countryId;
      if (!countryId) {
        throw new NotFoundException(
          errorMessages.countryNotFoundForPolicy(policyId),
        );
      }

      const constraint = await this.policyRepository.manager.findOne(
        MstrPolicyConstraint,
        { where: { countryId } },
      );

      if (!constraint) {
        throw new NotFoundException(
          errorMessages.policyConstraintsNotFound(countryId),
        );
      }

      return constraint;
    } catch (error) {
      this.logger.error({
        level: "error",
        message: buildLogMessage({
          traceId: this.traceIdService.traceId,
          status: "failure",
          location: "PolicyRepository",
          method: "getPolicyConstraintsByPolicyId",
          payload: { policyId },
          messageData: error,
        }),
      });
      throw new InternalServerErrorException(
        error instanceof Error
          ? error.message
          : "Failed to fetch policy constraints.",
      );
    }
  }
