  async getActivePolicyFeatureDocument(
    policyId: number,
  ): Promise<{ data: unknown[]; count: number }> {
    try {
      this.logger.log({
        level: "info",
        message: buildLogMessage({
          traceId: this.traceIdService.traceId,
          status: "success",
          location: "PolicyRepository",
          method: "getActivePolicyFeatureDocument",
          payload: { policyId },
          messageData: "Fetching active policy feature document",
        }),
      });

      const [documents, count] =
        await this.policyFeatureDocumentRepository.findAndCount({
          where: {
            policyId,
            status: POLICY_FEATURE_DOCUMENT_STATUS.ACTIVE,
            deletedAt: IsNull(),
          },
          relations: ["fileUpload", "createdByUser"],
          order: {
            createdAt: "DESC",
          },
        });

      // Transform results to match the upload-history API response format
      const data = documents.map((doc) => ({
        id: doc.id,
        policyId: doc.policyId,
        documentId: doc.documentId,
        fileName:
          this.extractFileNameFromKey(doc.fileUpload?.fileKey) ||
          doc.fileUpload?.uploadType ||
          "Policy Feature Document",
        fileStatus: doc.status || "ACTIVE",
        uploadedAt: this.formatDate(doc.createdAt),
        uploadedBy: doc.createdBy,
        uploadedByName: doc.createdByUser
          ? `${doc.createdByUser.firstName || ""} ${
              doc.createdByUser.lastName || ""
            }`.trim()
          : "Unknown User",
      }));

      this.logger.log({
        level: "info",
        message: buildLogMessage({
          traceId: this.traceIdService.traceId,
          status: "success",
          location: "PolicyRepository",
          method: "getActivePolicyFeatureDocument",
          payload: { policyId, count },
          messageData: `Successfully fetched ${data.length} active policy feature document records`,
        }),
      });

      return { data, count };
    } catch (error) {
      this.logger.error({
        level: "error",
        message: buildLogMessage({
          traceId: this.traceIdService.traceId,
          status: "failure",
          location: "PolicyRepository",
          method: "getActivePolicyFeatureDocument",
          payload: { policyId },
          messageData: `Failed to fetch active policy feature document: ${
            (error as Error).message
          }`,
        }),
      });
      throw error;
    }
  }

